"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["92531"],{30064(e){e.exports=JSON.parse('{"id":"FIN-1368","slug":"purchase-price-allocation","term":"Purchase Price Allocation (PPA)","also_known_as":["PPA"],"difficulty":"Advanced","definition":"Purchase price allocation (PPA) is the process of assigning the price paid in an acquisition to the identifiable assets acquired and liabilities assumed, measured at fair value, with any remaining amount recorded as goodwill.","explanation":["When one company acquires another, accounting standards under IFRS and US GAAP require the buyer to record the target\'s assets and liabilities at their fair values on the acquisition date, not at their old book values.","This includes intangible assets that may not have appeared on the target\'s balance sheet, such as customer relationships, brands, technology and patents. Any excess of the purchase price over the net fair value of identifiable assets and liabilities is recorded as goodwill.","For example, a company pays 500,000,000 for a business whose identifiable assets and liabilities have a net fair value of 350,000,000, including newly recognised intangible assets. The remaining 150,000,000 is recorded as goodwill.","Purchase price allocation affects future profits. Intangible assets with limited lives are amortized, reducing reported earnings, while goodwill is not amortized but tested for impairment. Higher values for inventory and fixed assets also increase future costs. Specialist valuation firms are often hired to estimate fair values."],"note":"","total":1500,"prev":{"slug":"purchase-price-adjustment","term":"Purchase Price Adjustment"},"next":{"slug":"purchasing-managers-index","term":"Purchasing Managers\' Index (PMI)"}}')}}]);